// Generated from official FCC protected service contours and U.S. Census TIGER boundaries.
// Proposed LPTV contours use the NJPBA TVStudy planning map supplied Sept. 1, 2026.
// FCC data: https://geo.fcc.gov/api/contours/
// Surrounding state boundaries: https://tigerweb.geo.census.gov/
// FCC WFS records confirm the grouped WNJN/WNJB, WNJT/WNJS, and WLVT-TV/WPPT
// licenses share an RF channel and identical protected contour at one transmitter site.

export type CoverageCategory =
  | "nj-full"
  | "nj-low"
  | "nj-coming"
  | "neighbor-whyy"
  | "neighbor-wnet"
  | "neighbor-lehigh";

export const coverageMapViewBox = {"width":850,"height":980} as const;

const PROJECT_X_SCALE = 260.0052908342445;
const PROJECT_X_OFFSET = 19884.395680708545;
const PROJECT_Y_SCALE = -334.9915465032699;
const PROJECT_Y_OFFSET = 13972.398279645975;
const KM_PER_LATITUDE_DEGREE = 111.32;

function plannedContourPath(lat: number, lon: number, contoursKm: readonly (readonly number[])[]) {
  const kmPerLongitudeDegree = KM_PER_LATITUDE_DEGREE * Math.cos(lat * Math.PI / 180);
  return contoursKm.map((distances) => {
    const points = Array.from({ length: 72 }, (_, index) => {
      const azimuthDegrees = index * 5;
      const azimuthRadians = azimuthDegrees * Math.PI / 180;
      const segment = Math.floor(azimuthDegrees / 45) % 8;
      const progress = (azimuthDegrees % 45) / 45;
      const d0 = distances[(segment + 7) % 8];
      const d1 = distances[segment];
      const d2 = distances[(segment + 1) % 8];
      const d3 = distances[(segment + 2) % 8];
      const distanceKm = 0.5 * (
        (2 * d1) +
        (-d0 + d2) * progress +
        (2 * d0 - 5 * d1 + 4 * d2 - d3) * progress ** 2 +
        (-d0 + 3 * d1 - 3 * d2 + d3) * progress ** 3
      );
      const pointLat = lat + distanceKm * Math.cos(azimuthRadians) / KM_PER_LATITUDE_DEGREE;
      const pointLon = lon + distanceKm * Math.sin(azimuthRadians) / kmPerLongitudeDegree;
      const x = pointLon * PROJECT_X_SCALE + PROJECT_X_OFFSET;
      const y = pointLat * PROJECT_Y_SCALE + PROJECT_Y_OFFSET;
      return `${index === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`;
    });
    return `${points.join(" ")} Z`;
  }).join(" ");
}

